-- Move remaining privileged AP/PO correction and CRM follow-up bodies into private.
-- Public RPC contracts stay stable and run as SECURITY INVOKER.

create or replace function private.add_purchase_order_line_atomic(p_purchase_order_id uuid,p_inventory_item_id uuid,p_description text,p_quantity numeric,p_unit_cost numeric) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare u public.users%rowtype;po public.purchase_orders%rowtype;i public.inventory_items%rowtype;rid uuid;d text:=btrim(coalesce(p_description,'')); begin select * into u from public.users where auth_user_id=auth.uid() and active=true limit 1; if u.id is null then raise exception 'Employee identity unavailable'; end if; if not private.has_permission('manage_purchasing') then raise exception 'Permission denied'; end if; if p_purchase_order_id is null or p_quantity is null or p_quantity<=0 or p_unit_cost is null or p_unit_cost<0 then raise exception 'Valid PO, quantity and cost required'; end if; select * into po from public.purchase_orders where id=p_purchase_order_id for update; if not found then raise exception 'Purchase order not found'; end if; if po.status not in('draft','submitted','partial') then raise exception 'Purchase order can no longer be edited'; end if; if p_inventory_item_id is not null then select * into i from public.inventory_items where id=p_inventory_item_id; if not found then raise exception 'Inventory item not found'; end if; if d='' then d:=i.description; end if; end if; if d='' then raise exception 'Description required'; end if; if length(d)>500 then raise exception 'Description is too long'; end if; insert into public.purchase_order_items(purchase_order_id,inventory_item_id,description,quantity,unit_cost) values(po.id,p_inventory_item_id,d,p_quantity,p_unit_cost) returning id into rid; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(u.id,'add_purchase_order_line','purchase_order',po.id::text,jsonb_build_object('line_id',rid,'inventory_item_id',p_inventory_item_id,'description',d,'quantity',p_quantity,'unit_cost',p_unit_cost)); return rid; end $$;
create or replace function public.add_purchase_order_line_atomic(p_purchase_order_id uuid,p_inventory_item_id uuid,p_description text,p_quantity numeric,p_unit_cost numeric) returns uuid language sql security invoker set search_path='' as $$ select private.add_purchase_order_line_atomic(p_purchase_order_id,p_inventory_item_id,p_description,p_quantity,p_unit_cost) $$;

create or replace function private.update_purchase_order_line_atomic(p_line_id uuid,p_quantity numeric,p_unit_cost numeric,p_description text) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare u public.users%rowtype;x public.purchase_order_items%rowtype;po public.purchase_orders%rowtype;d text:=btrim(coalesce(p_description,'')); begin select * into u from public.users where auth_user_id=auth.uid() and active=true limit 1; if u.id is null then raise exception 'Employee identity unavailable'; end if; if not private.has_permission('manage_purchasing') then raise exception 'Permission denied'; end if; if p_line_id is null or p_quantity is null or p_quantity<=0 or p_unit_cost is null or p_unit_cost<0 or d='' or length(d)>500 then raise exception 'Valid line values required'; end if; select * into x from public.purchase_order_items where id=p_line_id for update; if not found then raise exception 'Purchase order line not found'; end if; select * into po from public.purchase_orders where id=x.purchase_order_id for update; if po.status not in('draft','submitted','partial') then raise exception 'Purchase order can no longer be edited'; end if; if x.received_quantity>0 then raise exception 'Received lines are locked; use a correction workflow rather than rewriting receipt history'; end if; update public.purchase_order_items set description=d,quantity=p_quantity,unit_cost=p_unit_cost where id=x.id; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,before_data,after_data) values(u.id,'update_purchase_order_line','purchase_order',po.id::text,jsonb_build_object('line_id',x.id,'description',x.description,'quantity',x.quantity,'unit_cost',x.unit_cost),jsonb_build_object('line_id',x.id,'description',d,'quantity',p_quantity,'unit_cost',p_unit_cost)); return x.id; end $$;
create or replace function public.update_purchase_order_line_atomic(p_line_id uuid,p_quantity numeric,p_unit_cost numeric,p_description text) returns uuid language sql security invoker set search_path='' as $$ select private.update_purchase_order_line_atomic(p_line_id,p_quantity,p_unit_cost,p_description) $$;

create or replace function private.remove_purchase_order_line_atomic(p_line_id uuid,p_reason text) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare u public.users%rowtype;x public.purchase_order_items%rowtype;po public.purchase_orders%rowtype;r text:=btrim(coalesce(p_reason,'')); begin select * into u from public.users where auth_user_id=auth.uid() and active=true limit 1; if u.id is null then raise exception 'Employee identity unavailable'; end if; if not private.has_permission('manage_purchasing') then raise exception 'Permission denied'; end if; if length(r)<3 or length(r)>1000 then raise exception 'Removal reason required'; end if; select * into x from public.purchase_order_items where id=p_line_id for update; if not found then raise exception 'Purchase order line not found'; end if; select * into po from public.purchase_orders where id=x.purchase_order_id for update; if po.status not in('draft','submitted','partial') then raise exception 'Purchase order can no longer be edited'; end if; if x.received_quantity>0 then raise exception 'Received lines cannot be removed'; end if; delete from public.purchase_order_items where id=x.id; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,before_data,after_data) values(u.id,'remove_purchase_order_line','purchase_order',po.id::text,to_jsonb(x),jsonb_build_object('removed',true,'reason',r)); return x.id; end $$;
create or replace function public.remove_purchase_order_line_atomic(p_line_id uuid,p_reason text) returns uuid language sql security invoker set search_path='' as $$ select private.remove_purchase_order_line_atomic(p_line_id,p_reason) $$;

create or replace function private.create_job_material_stage(p_purchase_order_id uuid,p_job_id uuid,p_inventory_item_id uuid,p_quantity numeric,p_staging_location text) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare a public.users%rowtype;rid uuid; begin if not private.has_permission('manage_staging') then raise exception 'Permission denied'; end if; select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1; if a.id is null then raise exception 'Employee identity unavailable'; end if; rid:=public.create_job_material_stage_impl(p_purchase_order_id,p_job_id,p_inventory_item_id,p_quantity,p_staging_location); insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(a.id,'create_job_material_stage','job_material_staging',rid::text,jsonb_build_object('purchase_order_id',p_purchase_order_id,'job_id',p_job_id,'inventory_item_id',p_inventory_item_id,'quantity',p_quantity,'staging_location',p_staging_location)); return rid; end $$;
create or replace function public.create_job_material_stage(p_purchase_order_id uuid,p_job_id uuid,p_inventory_item_id uuid,p_quantity numeric,p_staging_location text) returns uuid language sql security invoker set search_path='' as $$ select private.create_job_material_stage(p_purchase_order_id,p_job_id,p_inventory_item_id,p_quantity,p_staging_location) $$;

create or replace function private.reverse_ap_payment_atomic(p_payment_id uuid,p_reason text) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare u public.users%rowtype;p public.ap_payments%rowtype;a public.accounts_payable_entries%rowtype;r text:=btrim(coalesce(p_reason,''));nb numeric;ns text; begin select * into u from public.users where auth_user_id=auth.uid() and active=true limit 1; if u.id is null then raise exception 'Employee identity unavailable'; end if; if not private.has_permission('manage_accounting') then raise exception 'Permission denied'; end if; if length(r)<3 or length(r)>1000 then raise exception 'Reversal reason required'; end if; select * into p from public.ap_payments where id=p_payment_id for update; if not found or p.accounts_payable_entry_id is null then raise exception 'Payment not found'; end if; if p.reversed_at is not null then raise exception 'Payment is already reversed'; end if; select * into a from public.accounts_payable_entries where id=p.accounts_payable_entry_id for update; if not found then raise exception 'AP bill not found'; end if; if a.status='void' then raise exception 'Void AP bills cannot have payments reversed'; end if; nb:=least(a.total,a.balance_due+p.amount); ns:=case when nb>=a.total-0.005 then 'open' else 'partial' end; update public.ap_payments set reversed_at=now(),reversed_by=u.id,reversal_reason=r where id=p.id; update public.accounts_payable_entries set balance_due=nb,status=ns where id=a.id; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,before_data,after_data) values(u.id,'reverse_ap_payment','accounts_payable_entry',a.id::text,jsonb_build_object('payment_id',p.id,'amount',p.amount,'balance_due',a.balance_due,'status',a.status),jsonb_build_object('payment_id',p.id,'reversed',true,'reason',r,'balance_due',nb,'status',ns)); return p.id; end $$;
create or replace function public.reverse_ap_payment_atomic(p_payment_id uuid,p_reason text) returns uuid language sql security invoker set search_path='' as $$ select private.reverse_ap_payment_atomic(p_payment_id,p_reason) $$;

create or replace function private.reverse_job_cost_allocation_atomic(p_allocation_id uuid,p_reason text) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare u public.users%rowtype;x public.job_cost_allocations%rowtype;r text:=btrim(coalesce(p_reason,'')); begin select * into u from public.users where auth_user_id=auth.uid() and active=true limit 1; if u.id is null then raise exception 'Employee identity unavailable'; end if; if not private.has_permission('manage_accounting') then raise exception 'Permission denied'; end if; if length(r)<3 or length(r)>1000 then raise exception 'Reversal reason required'; end if; select * into x from public.job_cost_allocations where id=p_allocation_id for update; if not found then raise exception 'Allocation not found'; end if; if x.reversed_at is not null then raise exception 'Allocation is already reversed'; end if; update public.job_cost_allocations set reversed_at=now(),reversed_by=u.id,reversal_reason=r where id=x.id; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,before_data,after_data) values(u.id,'reverse_job_cost_allocation','job',x.job_id::text,jsonb_build_object('allocation_id',x.id,'amount',x.amount,'type',x.allocation_type,'accounts_payable_entry_id',x.accounts_payable_entry_id),jsonb_build_object('allocation_id',x.id,'reversed',true,'reason',r)); return x.id; end $$;
create or replace function public.reverse_job_cost_allocation_atomic(p_allocation_id uuid,p_reason text) returns uuid language sql security invoker set search_path='' as $$ select private.reverse_job_cost_allocation_atomic(p_allocation_id,p_reason) $$;

create or replace function private.void_ap_entry_atomic(p_ap_id uuid,p_reason text) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare u public.users%rowtype;a public.accounts_payable_entries%rowtype;r text:=btrim(coalesce(p_reason,'')); begin select * into u from public.users where auth_user_id=auth.uid() and active=true limit 1; if u.id is null then raise exception 'Employee identity unavailable'; end if; if not private.has_permission('manage_accounting') then raise exception 'Permission denied'; end if; if length(r)<3 or length(r)>1000 then raise exception 'Void reason required'; end if; select * into a from public.accounts_payable_entries where id=p_ap_id for update; if not found then raise exception 'AP bill not found'; end if; if a.status='void' then raise exception 'AP bill is already void'; end if; if exists(select 1 from public.ap_payments where accounts_payable_entry_id=a.id and reversed_at is null) then raise exception 'Reverse active payments before voiding this AP bill'; end if; if exists(select 1 from public.job_cost_allocations where accounts_payable_entry_id=a.id and reversed_at is null) then raise exception 'Reverse active job allocations before voiding this AP bill'; end if; update public.accounts_payable_entries set status='void',balance_due=0,memo=concat_ws(' | ',nullif(a.memo,''),'VOID: '||r) where id=a.id; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,before_data,after_data) values(u.id,'void_ap_entry','accounts_payable_entry',a.id::text,jsonb_build_object('status',a.status,'balance_due',a.balance_due),jsonb_build_object('status','void','balance_due',0,'reason',r)); return a.id; end $$;
create or replace function public.void_ap_entry_atomic(p_ap_id uuid,p_reason text) returns uuid language sql security invoker set search_path='' as $$ select private.void_ap_entry_atomic(p_ap_id,p_reason) $$;

create or replace function private.record_customer_followup_atomic(p_customer_id uuid,p_equipment_id uuid,p_channel text,p_outcome text,p_notes text,p_follow_up_at timestamptz) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare a public.users%rowtype;fid uuid; begin select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1; if a.id is null then raise exception 'Employee identity unavailable'; end if; if not private.has_permission('manage_opportunities') then raise exception 'Permission denied'; end if; if p_customer_id is null or not exists(select 1 from public.customers where id=p_customer_id) then raise exception 'Customer required'; end if; if p_equipment_id is not null and not exists(select 1 from public.customer_equipment where id=p_equipment_id and customer_id=p_customer_id) then raise exception 'Equipment does not belong to customer'; end if; if p_channel not in('phone','sms','email','other') then raise exception 'Invalid channel'; end if; if p_outcome not in('no_answer','left_message','spoke_not_ready','callback','booked','declined','other') then raise exception 'Invalid outcome'; end if; if length(coalesce(p_notes,''))>3000 then raise exception 'Notes too long'; end if; insert into public.customer_followups(customer_id,equipment_id,csr_user_id,channel,outcome,notes,follow_up_at) values(p_customer_id,p_equipment_id,a.id,p_channel,p_outcome,nullif(btrim(coalesce(p_notes,'')),''),p_follow_up_at) returning id into fid; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(a.id,'record_customer_followup','customer',p_customer_id::text,jsonb_build_object('followup_id',fid,'channel',p_channel,'outcome',p_outcome,'follow_up_at',p_follow_up_at)); return fid; end $$;
create or replace function public.record_customer_followup_atomic(p_customer_id uuid,p_equipment_id uuid,p_channel text,p_outcome text,p_notes text,p_follow_up_at timestamptz) returns uuid language sql security invoker set search_path='' as $$ select private.record_customer_followup_atomic(p_customer_id,p_equipment_id,p_channel,p_outcome,p_notes,p_follow_up_at) $$;

